# -*- coding: utf-8 -*-
"""Lote 1 · parte B: anestesiología y fisiología cardiovascular."""
from lote01a import Q, L

Q(a="cirugia", cat=None, tema="Lidocaína como antiarrítmico", año=2014, ext=False,
  e="La lidocaína es un anestésico local, que también es utilizado en arritmias...",
  o=["Ventriculares.", "Auriculares.", "Supraventriculares.", "Refractarias.", "Auriculoventriculares."], k="A",
  c="La lidocaína es un anestésico local del grupo amida que además actúa como antiarrítmico de clase Ib: bloquea los canales de sodio en estado inactivado, de modo que actúa de forma selectiva en el tejido isquémico o despolarizado del ventrículo, acorta el potencial de acción y suprime los focos ectópicos ventriculares. Por eso se usó en las arritmias ventriculares del infarto, la intoxicación digitálica y la cirugía cardiaca. Hoy, en el paro por fibrilación o taquicardia ventricular sin pulso refractaria a descargas, las guías AHA 2020/2025 consideran amiodarona o lidocaína como alternativa. No es eficaz en arritmias auriculares o supraventriculares, porque el tejido auricular tiene potenciales de acción cortos y se recupera rápido del bloqueo. Toxicidad: parestesias periorales, tinnitus, convulsiones y arritmias.",
  f="AHA, Soporte Vital Cardiovascular Avanzado (actualización 2025); Goodman & Gilman Bases Farmacológicas de la Terapéutica 14.ª ed.")

Q(a="cirugia", cat=None, tema="Complicación más frecuente de la anestesia raquídea", año=2014, ext=False,
  e="¿Cuál es la complicación más frecuente de la anestesia raquídea?",
  o=["Vértigo.", "Parestesias.", "Hipotensión.", "Meningitis.", "Urticaria."], k="C",
  c="La hipotensión es la complicación más frecuente de la anestesia raquídea. El bloqueo simpático (fibras preganglionares T1-L2) produce vasodilatación arterial y, sobre todo, venodilatación con caída del retorno venoso y del gasto cardiaco; si el bloqueo sube hasta T1-T4 también se bloquean las fibras cardioaceleradoras y aparece bradicardia (reflejo de Bezold-Jarisch). El riesgo aumenta con el nivel alcanzado, la hipovolemia, el ayuno prolongado, la obesidad y el embarazo (compresión aortocava). Prevención y manejo: precarga o cocarga con cristaloides, desplazamiento uterino lateral en la gestante, y vasopresor (fenilefrina o efedrina; la noradrenalina en dosis bajas es una alternativa en cesárea) y atropina si hay bradicardia. La cefalea pospunción y la meningitis son mucho menos frecuentes.",
  f="Miller Anestesia 9.ª ed.; ASA, Practice Guidelines for Obstetric Anesthesia (2016).")

Q(a="cirugia", cat=None, tema="Anestésicos locales tipo éster", año=2014, ext=False,
  e="¿Cuál de los siguientes anestésicos locales tiene el grupo éster?",
  o=["Lidocaína.", "Bupivacaína.", "Mepivacaína.", "Procaína.", "Ropivacaína."], k="D",
  c="Los anestésicos locales se clasifican por el enlace químico entre el anillo aromático y la cadena amínica. Los ésteres (procaína, tetracaína, cocaína, cloroprocaína, benzocaína) se hidrolizan en plasma por las colinesterasas y producen PABA, metabolito que causa alergia, por eso son poco usados. Las amidas (lidocaína, mepivacaína, bupivacaína, ropivacaína, prilocaína, articaína) se metabolizan en el hígado y rara vez causan alergia verdadera. Truco mnemotécnico: las amidas tienen «i» antes de «caína» (lidocaína, bupivacaína), los ésteres no. Aplicación: en un paciente con hepatopatía grave se reduce la dosis de amidas; con deficiencia de colinesterasa plasmática, la de ésteres.",
  f="Miller Anestesia 9.ª ed.; Goodman & Gilman Bases Farmacológicas de la Terapéutica 14.ª ed.")

Q(a="cirugia", cat=None, tema="Anestésicos locales: grupo éster (variante)", año=2014, ext=False,
  e="¿Cuál de los siguientes anestésicos locales es del grupo ésteres?",
  o=["Procaína.", "Lidocaína.", "Bupivacaína.", "Mepivacaína.", "Prilocaína."], k="A",
  c="La procaína es el único éster de la lista; todos los demás (lidocaína, bupivacaína, mepivacaína y prilocaína) son amidas. La diferencia tiene consecuencias clínicas: los ésteres son inestables, se degradan rápido por seudocolinesterasa y generan ácido paraaminobenzoico (PABA), responsable de las reacciones alérgicas; las amidas son más estables, duran más y se metabolizan en el hígado por el citocromo P450. La cocaína, también éster, es el único anestésico local con propiedades vasoconstrictoras propias. Los anestésicos locales bloquean el canal de sodio dependiente de voltaje desde dentro de la célula, y la forma no ionizada es la que atraviesa la membrana: en tejido infectado y ácido, el efecto disminuye.",
  f="Miller Anestesia 9.ª ed.; Katzung Farmacología Básica y Clínica 15.ª ed.")

Q(a="cirugia", cat=None, tema="Anestesia raquídea: espacio subaracnoideo", año=2016, ext=False,
  e="La anestesia raquídea se logra mediante la inyección del anestésico a nivel:",
  o=["Subaracnoideo.", "Epidural.", "Local.", "Sitio operatorio.", "Plexo lumbar."], k="A",
  c="La anestesia raquídea (espinal o subaracnoidea) se logra al inyectar un volumen pequeño de anestésico local con una aguja fina en el espacio subaracnoideo, dentro del líquido cefalorraquídeo, habitualmente a nivel L3-L4 o L4-L5, por debajo del cono medular (que termina en L1-L2 del adulto), para evitar lesionarlo. Se logra un bloqueo rápido, denso y simétrico con dosis bajas. En cambio, la anestesia epidural coloca el fármaco en el espacio epidural, fuera de la duramadre, necesita volúmenes mayores, tiene un inicio más lento y permite colocar un catéter para analgesia continua (por ejemplo, analgesia del trabajo de parto). Ambas son técnicas neuroaxiales. Contraindicaciones absolutas de la raquídea: rechazo del paciente, infección en el sitio de punción, coagulopatía y aumento de la presión intracraneal.",
  f="Miller Anestesia 9.ª ed.; ASRA, anestesia regional en pacientes anticoagulados (4.ª ed., 2018).")

Q(a="cirugia", cat=None, tema="Clasificación ASA en insuficiencia cardiaca", año=2016, ext=False,
  e="Mujer de 70 años con diagnóstico de colecistitis aguda. Antecedente: insuficiencia cardíaca congestiva. ¿Cuál es la escala ASA que le corresponde desde el punto de vista anestesiológico?",
  o=["IV.", "II.", "III.", "V.", "VI."], k="A",
  c="La clasificación de la American Society of Anesthesiologists (ASA) estima el riesgo anestésico según las comorbilidades: I sano; II enfermedad sistémica leve; III enfermedad sistémica grave con limitación funcional; IV enfermedad sistémica grave que es amenaza constante para la vida; V moribundo que no sobrevivirá sin la cirugía; VI muerte cerebral, donante de órganos; se añade «E» si es urgencia. La insuficiencia cardiaca bien compensada se considera ASA III; la descompensada o con síntomas en reposo y un proceso séptico agudo como la colecistitis (con riesgo de descompensación) se asigna ASA IV. La clave del libro es IV: en el examen se espera esa lógica de «cardiopatía incapacitante + cuadro agudo». Una cirugía urgente en ASA IV tiene mortalidad perioperatoria elevada y requiere monitorización invasiva y optimización mínima.",
  f="ASA, Physical Status Classification System (actualización 2020); Miller Anestesia 9.ª ed.",
  nota="Clave del libro: IV. Si la insuficiencia cardiaca estuviera compensada sería ASA III; se explica en el comentario.")

Q(a="cirugia", cat=None, tema="Hipotensión en anestesia raquídea del paciente deshidratado", año=2017, ext=False,
  e="¿Cuál es la complicación más frecuente de la anestesia raquídea, en pacientes que no están bien hidratados?",
  o=["Hipotensión.", "Parestesias.", "Bradicardia.", "Inconsciencia.", "Cefalea."], k="A",
  c="En el paciente hipovolémico o mal hidratado el bloqueo simpático de la raquídea es más peligroso: la venodilatación que reduce el retorno venoso se suma a un volumen circulante ya bajo, y la hipotensión puede ser profunda y rápida. Mecanismos: vasodilatación, disminución del retorno venoso y caída del gasto cardiaco; si el bloqueo es alto (T4 o más), se suma la bradicardia por bloqueo de las fibras cardioaceleradoras. Se previene reponiendo el volumen antes de la punción (precarga o cocarga con cristaloides), y se trata con vasopresores (fenilefrina, efedrina) y atropina si hay bradicardia. Las parestesias suelen ser transitorias, la cefalea pospunción aparece en las primeras 72 horas y se alivia en decúbito, y la inconsciencia indicaría una raquídea total, una complicación rara y grave.",
  f="Miller Anestesia 9.ª ed.; Barash Anestesia Clínica 8.ª ed.")

Q(a="cirugia", cat=None, tema="Anestesia neuroaxial: tipo regional", año=2018, ext=False,
  e="¿Cómo se denomina el tipo de anestesia neuroaxial de aplicación extradural en la periferia?",
  o=["Sedación.", "Endovenosa.", "Subdural.", "General.", "Regional."], k="E",
  c="La anestesia neuroaxial es una forma de anestesia regional: el anestésico local se aplica cerca de las raíces nerviosas, en el espacio subaracnoideo (raquídea) o en el espacio extradural o epidural (peridural). Desde el punto de vista de la clasificación, la anestesia puede ser general (con pérdida de la conciencia), regional (bloqueo neuroaxial o de nervios periféricos), local o sedación. Como la pregunta busca el nombre general del tipo de técnica y no figura «epidural» entre las alternativas, la mejor opción es «regional». Recuerda que el espacio «subdural» no es un espacio anatómico real: la inyección subdural inadvertida produce un bloqueo extenso, irregular y de inicio tardío.",
  f="Miller Anestesia 9.ª ed.; Barash Anestesia Clínica 8.ª ed.",
  nota="Pregunta de redacción ambigua; se mantiene la clave del libro (regional).")

Q(a="cirugia", cat=None, tema="Complicación más frecuente de la anestesia epidural", año=2018, ext=False,
  e="Varón de 36 años con quemadura de 2.º grado en el 45 % de la superficie corporal y de 3.er grado en miembros inferiores; se indica fasciotomía. En el preoperatorio se administra 2 L de solución salina EV. ¿Cuál es la complicación más frecuente de la anestesia epidural?",
  o=["Cardiopatía isquémica.", "Relajación muscular.", "Hipotensión arterial.", "Parálisis respiratoria.", "Cefalea intensa."], k="C",
  c="La complicación más frecuente de la anestesia regional neuroaxial, epidural y sobre todo raquídea, es la hipotensión arterial por bloqueo simpático (vasodilatación y venodilatación). En un gran quemado el riesgo aumenta porque hay hipovolemia, pérdida de plasma al tercer espacio y respuesta inflamatoria sistémica; por eso la reposición con cristaloides y el uso de vasopresores deben estar listos. Con la epidural el inicio es más gradual que con la raquídea, de modo que la hipotensión suele ser menos brusca. La cefalea pospunción solo ocurre si hay punción accidental de la duramadre; la parálisis respiratoria se ve con bloqueos muy altos. La relajación muscular es un efecto buscado, no una complicación.",
  f="Miller Anestesia 9.ª ed.; ISBI, Practice Guidelines for Burn Care (2016 y 2018).")

Q(a="cirugia", cat=None, tema="Anestésico local de acción prolongada", año=2019, ext=False,
  e="Mujer de 48 años con hernia inguinal izquierda crónica a quien el anestesiólogo decide colocar anestesia epidural. ¿Qué anestésico de acción prolongada se recomienda?",
  o=["Articaína.", "Lidocaína.", "Cloroprocaína.", "Mepivacaína.", "Bupivacaína."], k="E",
  c="La duración de un anestésico local depende de su liposolubilidad y de su unión a proteínas. La bupivacaína (y la ropivacaína y la levobupivacaína) son de acción prolongada (2 a 8 horas), muy liposolubles y con alta unión proteica; la lidocaína y la mepivacaína son de acción intermedia (1 a 2 horas); la articaína y la cloroprocaína son de acción corta (30 a 60 minutos). La bupivacaína tiene mayor cardiotoxicidad porque se une con fuerza al canal de sodio cardiaco: se evitan las inyecciones intravasculares accidentales y la dosis máxima es de 2,5 mg/kg. Ante una intoxicación grave se emplea emulsión lipídica al 20 % (bolo de 1,5 mL/kg). En una hernia inguinal se busca analgesia posoperatoria prolongada, de ahí la bupivacaína.",
  f="Miller Anestesia 9.ª ed.; ASRA, guía de toxicidad sistémica por anestésicos locales (2020).")

Q(a="cirugia", cat=None, tema="Tipo de anestesia en peritonitis difusa", año=2019, ext=False,
  e="Mujer de 20 años con peritonitis difusa por apendicitis complicada que va a ser intervenida quirúrgicamente. ¿Cuál es el tipo de anestesia más adecuado?",
  o=["Espinal.", "Epidural.", "Con uso de máscara laríngea.", "General.", "Con uso de óxido nitroso."], k="D",
  c="La anestesia depende del tipo de cirugía y del estado del paciente. Una peritonitis difusa requiere laparotomía o laparoscopia con lavado de la cavidad, exploración amplia y relajación muscular completa, y el paciente suele estar séptico, con íleo y con riesgo de broncoaspiración, por lo que se indica anestesia general con intubación endotraqueal y secuencia rápida (inducción con presión cricoidea o sin ella según el protocolo local). La raquídea y la epidural están contraindicadas relativamente por la sepsis (hipotensión grave, riesgo de infección neuroaxial) y porque no protegen la vía aérea. La máscara laríngea no protege contra la aspiración y el óxido nitroso está contraindicado por el íleo, pues se difunde a las asas y las distiende más.",
  f="Miller Anestesia 9.ª ed.; Sabiston Tratado de Cirugía 21.ª ed.")

Q(a="ciencias_basicas", cat="Fisiología", tema="Flujo sanguíneo por 100 g de tejido", año=2014, ext=False,
  e="¿Cuál de los siguientes órganos tiene el mayor flujo sanguíneo por 100 g de tejido?",
  o=["Riñón.", "Cerebro.", "Miocardio.", "Piel.", "Hígado."], k="A",
  c="El flujo sanguíneo por gramo de tejido es mayor en los órganos que filtran o necesitan una perfusión muy alta para su función: el riñón recibe cerca del 20-25 % del gasto cardiaco (unos 1100 mL/min) en solo 300 g de tejido, es decir, alrededor de 350-400 mL/min/100 g, muy por encima del cerebro (50 mL/min/100 g) y del miocardio (70-80 mL/min/100 g en reposo). El hígado recibe el mayor flujo absoluto (≈ 1350 mL/min, por vena porta y arteria hepática) pero su masa es de 1,5 kg, así que su flujo por 100 g es de 90-100. El alto flujo renal sirve para la filtración glomerular, no para el consumo de oxígeno: por eso la diferencia arteriovenosa de O₂ del riñón es pequeña.",
  f="Guyton y Hall Tratado de Fisiología Médica 14.ª ed.; Boron y Boulpaep Fisiología Médica 3.ª ed.")

Q(a="ciencias_basicas", cat="Fisiología", tema="Período refractario absoluto del miocito", año=2014, ext=False,
  e="En relación al período refractario absoluto en despolarización celular del miocito, señale lo correcto:",
  o=["Es el momento del potencial de acción en que la célula no puede responder a un estímulo.",
     "Es el momento del potencial de acción en que la célula puede responder a un estímulo de menor intensidad.",
     "Es el momento del potencial de acción en que la célula responde a un estímulo de mayor intensidad.",
     "Es el momento del potencial de acción en que la célula responde a un estímulo similar al estímulo inicial.",
     "Se debe al flujo de calcio hacia el espacio intracelular."], k="A",
  c="Durante el período refractario absoluto (fases 0, 1, 2 y gran parte de la 3 del potencial de acción del miocito) los canales de sodio rápidos están inactivados y la célula no puede generar otro potencial de acción, sea cual sea la intensidad del estímulo. Después sigue el período refractario relativo, en el que un estímulo supraumbral puede producir un potencial de acción de menor amplitud. La larga meseta del potencial de acción cardiaco (fase 2, por entrada de calcio) prolonga la refractariedad y evita el tétanos del miocardio, lo que permite que el corazón se relaje y se llene. Corresponde en el ECG al complejo QRS, el segmento ST y la primera parte de la onda T; la fase vulnerable es el pico de la onda T, donde un estímulo fuerte puede desencadenar fibrilación ventricular (fenómeno R sobre T).",
  f="Guyton y Hall Tratado de Fisiología Médica 14.ª ed.; Braunwald Tratado de Cardiología 12.ª ed.")
